const HIST18_NOTES = [
 {t:"§1. Индия: природа и занятия жителей", h:`
  <p>На полуострове <b>Индостан</b> ещё в период Древнего мира сложилась <b>индо-буддийская цивилизация</b>.</p>
  <div class="rule">Основное занятие жителей — сельское хозяйство. Жаркий и влажный климат Южной Азии позволял снимать по два-три урожая в год.</div>
  <ul>
   <li>Выращивали <b>хлопчатник, сахарный тростник, рис</b>, овощи и фрукты; разводили скот (кожа и шерсть шли на одежду).</li>
   <li><b>Джунгли</b> — настоящая сокровищница: дерево, пряности, благовония, красители. Охотились на оленей, кабанов, антилоп; собирали бананы, манго, цитрусовые; ловили рыбу.</li>
   <li>Богатые недра способствовали развитию <b>ремёсел</b>: изделия из железа, меди, золота и серебра, драгоценных камней; оружие, изящные сосуды, изделия из слоновой кости, яркие ткани, пряности и благовония — предметы <b>торговли с другими странами</b>.</li>
  </ul>
  <div class="ex">В 1471–1474 гг. в Индии побывал тверской купец Афанасий Никитин, оставивший путевые записки «Хождение за три моря». Он достиг Индии почти на 30 лет раньше португальского мореплавателя Васко да Гамы.</div>`},
 {t:"§2. Общество: варны и касты", h:`
  <div class="rule">Деление на варны сохранилось с Древнего мира, но внутри варн стали формироваться более мелкие группы по профессиональному признаку — касты.</div>
  <p>К высшим слоям общества относились <b>махараджи</b> (цари), <b>раджи</b> (князья) и <b>брахманы</b>.</p>
  <table>
   <thead><tr><th>Варна</th><th>Кто входил</th></tr></thead>
   <tbody>
    <tr><td><b>Брахманы</b> («мудрецы»)</td><td>жрецы, учителя, врачи</td></tr>
    <tr><td><b>Кшатрии</b> («воины»)</td><td>военные, государственные чиновники, земледельческая знать</td></tr>
    <tr><td><b>Вайшьи</b> («свободные общинники»)</td><td>купцы, скотоводы, ростовщики, земледельцы</td></tr>
    <tr><td><b>Шудры</b> («слуги»)</td><td>кожевники, ткачи, пастухи, прачки, музыканты, гончары</td></tr>
    <tr><td><b>Неприкасаемые</b></td><td>уборщики мусора и нечистот — самые низы общества</td></tr>
   </tbody>
  </table>
  <ul>
   <li>Большинство жителей Индии — <b>вайшьи</b>-земледельцы, объединявшиеся в <b>общины</b> для совместного хозяйства.</li>
   <li><b>Шестую часть урожая</b> община платила радже — собственнику земли. Эти средства шли на содержание воинов и чиновников, поддержку храмов и жрецов-брахманов.</li>
   <li>Общинники участвовали в деревенском самоуправлении, вместе строили дороги и укрепления, организовывали праздники.</li>
   <li>Городские ремесленники и торговцы тоже объединялись в касты — по роду занятий или товару. Большую часть налогов горожане платили <b>не деньгами, а изделиями и товарами</b>.</li>
   <li>Жизнью каст руководили <b>старейшины</b>: следили за выполнением правил и обычаев, судили провинившихся. Одно из самых страшных наказаний — <b>изгнание из касты</b>; такие люди пополняли ряды неприкасаемых.</li>
  </ul>
  <div class="trap">⚠️ Существование замкнутых каст разобщало население Индии.</div>`},
 {t:"§3. Индия в IV–IX вв.: религии и государства", h:`
  <ul>
   <li>Большинство населения исповедовало <b>индуизм</b>. Индусы поклонялись 33 тысячам богов; божества покровительствовали профессиям и местностям. Главные боги — <b>Брахма, Шива и Вишну</b>, считавшиеся творцами Вселенной.</li>
   <li>Индуисты верили в <b>перевоплощение душ</b>: кто ведёт праведный образ жизни — родится в более знатной семье; кто нарушает правила — перевоплотится в человека низшей касты или даже в животное. Поэтому многие отказывались от мяса: считалось, что, съев его, можно погубить душу человека.</li>
   <li>Вторая религия — <b>буддизм</b> (зародился ещё в эпоху Древнего мира): призывал к отказу от желаний и достижению гармонии с миром — <b>нирваны</b>.</li>
   <li>Цари династии <b>Гуптов</b> покровительствовали буддизму и индуизму; их правление — <b>время расцвета средневековой Индии</b>. Они подчинили своей власти весь Север Индии, а правители Южной Индии платили дань. Но «золотой век» был недолгим.</li>
   <li>Во второй половине V — начале VI в. северо-западные земли захватили кочевники-<b>эфталиты</b>. Они расселились в долине Ганга и Центральной Индии и образовали касту <b>раджпутов</b> («сыновей раджи») — воинов, отличавшихся свирепостью в бою и верностью своему правителю.</li>
   <li>Царь <b>Харша (606–647)</b> временно объединил Северную и центральную части Индии. Вошёл в историю не только как успешный правитель, но и как <b>поэт и драматург</b>.</li>
   <li>После смерти Харши держава <b>распалась</b>: возникло множество небольших государств, правители которых постоянно воевали друг с другом; династии сменяли друг друга.</li>
  </ul>`},
 {t:"§4. Мусульманское завоевание и Делийский султанат", h:`
  <ul>
   <li><b>VII — начало VIII в.</b> — попытку завоевать Индию предприняли <b>арабы</b>: им удалось завоевать <b>западную часть</b> страны (712 г.). Но раджпуты и правители Северной Индии <b>объединили войска</b>, дали решительный отпор и изгнали завоевателей.</li>
   <li><b>1001 г.</b> — Индия вновь подверглась нападению, теперь со стороны <b>тюрок</b>. Султан <b>Махмуд Газневи (998–1030)</b>, правивший государством на территории современного Афганистана, совершил <b>17 походов</b> в Индию, разрушая города и возвращаясь с богатой добычей.</li>
   <li>За сто лет беспрерывных походов завоевателям удалось подчинить почти всю Северную Индию. В <b>1206 г.</b> тюрки провозгласили создание <b>Делийского султаната</b>.</li>
  </ul>
  <div class="rule">Порядки в Делийском султанате: вся земля — собственность государства; часть земельных владений султаны предоставляли исламскому духовенству, другую передавали воинам в обмен на службу.</div>
  <ul>
   <li>Индийская знать была вынуждена подчиниться мусульманским правителям: служить им и выплачивать <b>дань</b>.</li>
   <li>Налоги с простолюдинов доходили <b>до половины урожая</b>; льготы получили только мусульмане.</li>
   <li>Местное население в основном <b>придерживалось веры предков</b>: ислам приняли лишь некоторые раджи, городские торговцы и небольшая часть крестьянства.</li>
   <li>В конце XIII — начале XIV в. правители султаната дали отпор <b>монголам</b>, а успешные походы на юг расширили территорию. Но власть султанов была непрочной.</li>
   <li><b>1398 г.</b> — вторжение среднеазиатского правителя <b>Тимура (Тамерлана)</b>. Его войска грабили Дели, убивали жителей и, угнав в Самарканд тысячи пленников, оставили после себя выжженную пустыню.</li>
  </ul>
  <div class="trap">⚠️ Последствия нашествия Тимура: Делийский султанат так и не оправился. От него одна за другой откалывались провинции, объявлявшие себя независимыми государствами; султаны смогли сохранить власть только на севере страны.</div>`},
 {t:"§5. Культура и наука Индии", h:`
  <p>Развитие культуры было тесно связано с религиозными верованиями — особенно заметно в архитектуре и изобразительном искусстве.</p>
  <ul>
   <li>Шедевр эпохи Гуптов — буддийский пещерный монастырь <b>Аджанта</b>: стены покрыты фресками со сценами из жизни Будды. (Но, несмотря на покровительство властей, буддизм в Индии постепенно терял приверженцев.)</li>
   <li>До IX в. индуистские храмы создавали в пещерах или высекали в скале-монолите, украшая изображениями и скульптурами богов (пещерные храмы на острове <b>Элефанта</b>, прославляющие Шиву); впоследствии возводили величественные <b>храмы-башни</b>.</li>
   <li>Значительное влияние оказал <b>ислам</b>: запрет изображать человека отрицательно повлиял на скульптуру и живопись — статуи и фрески во многих индуистских и буддийских храмах были испорчены, создавать новые запрещалось. Зато началось возведение <b>мечетей, минаретов, медресе</b>.</li>
  </ul>
  <div class="ex">Минарет Кутб-Минар в Дели строили несколько поколений мусульманских правителей в 1193–1368 гг. Высота 72,6 м — это самый высокий в мире минарет, построенный из кирпича. На его стенах видны символы, не связанные с исламом: при строительстве использовали камни из разрушенных индуистских храмов. Для декора арабскую вязь сочетали с традиционной для Индии резьбой по камню.</div>
  <p><b>Наука.</b> Средневековье стало временем расцвета индийской науки:</p>
  <ul>
   <li>Математики придумали <b>цифру «ноль»</b> и создали <b>десятичную систему счёта</b>, распространившуюся в мире благодаря арабам; ввели понятия «синус», «косинус», «квадратный и кубический корень».</li>
   <li>Врачи знали о <b>трёхстах видах</b> медицинских операций и умели делать их при помощи <b>120 разных инструментов</b>.</li>
   <li>Широкое распространение получили <b>аюрведа и йога</b> — учения о правильном питании и дыхании.</li>
  </ul>
  <p><b>Языки.</b> На севере страны был распространён <b>санскрит</b>, на юге — десятки разных наречий. Жители различных княжеств зачастую не понимали друг друга; множество языков стало <b>препятствием для развития единой национальной литературы</b>.</p>
  <div class="rule">Итог параграфа: междоусобицы и политическая раздробленность облегчили завоевателям покорение средневековой Индии. Но традиционные верования, язык и культура позволили индийцам сохранить свой образ жизни, несмотря на завоевание.</div>`},
 {t:"Даты — шпаргалка", h:"__DATES_TABLE__"}
];
(function(){
  const rows=HIST18_DATES.slice().sort((a,b)=>yRange(a.y)[0]-yRange(b.y)[0]||a.y.localeCompare(b.y));
  const t=rows.map(d=>`<tr><td><b>${d.y.trim()}</b></td><td>${d.e}</td></tr>`).join('');
  HIST18_NOTES[HIST18_NOTES.length-1].h=`<table><thead><tr><th>Дата</th><th>Событие</th></tr></thead><tbody>${t}</tbody></table>
  <p><b>Подсказка:</b> «Россия» — что происходило в нашей стране в то же время (из колонок «Россия» в учебнике).</p>`;
})();

