function hist18Build(){
  const qs=HIST18_QUESTIONS.map(q=>Object.assign({type:"c",kind:"q"},q));
  HIST18_DATES.forEach(d=>{
    const others=HIST18_DATES.filter(o=>o!==d&&!overlap(o.y,d.y));
    const evOpts=[d.e,...shuffle(others.slice()).slice(0,3).map(o=>o.e)];
    const near=others.slice().sort((a,b)=>Math.abs(yRange(a.y)[0]-yRange(d.y)[0])-Math.abs(yRange(b.y)[0]-yRange(d.y)[0])).slice(0,7);
    const uniqY=[...new Set(shuffle(near).map(o=>o.y.trim()))].slice(0,3);
    const dOpts=[d.y.trim(),...uniqY];
    qs.push({type:"c",kind:"date",par:d.par,topic:"Даты: что произошло",q:`Что произошло в ${yr(d.y)}?`,opts:evOpts,ans:d.e,why:`${yr(d.y)} — ${d.e}.`});
    qs.push({type:"c",kind:"date",par:d.par,topic:"Даты: когда",q:`Когда? ${d.e}`,opts:dOpts,ans:d.y.trim(),why:`${d.e} — ${yr(d.y)}`});
  });
  return qs;
}

